if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Play required");
var runtime=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Runtime.EchoSphereRuntime>();var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
bool Paused()=>(bool)runtime.GetType().GetField("_userPaused",flags).GetValue(runtime);double RunTime()=>System.Convert.ToDouble(runtime.GetType().GetField("_runTime",flags).GetValue(runtime));
if(!runtime.UsesNativeHud||!runtime.UsesNativePauseStats)throw new System.Exception("Hold accepted diagnostic HUD enabled for this paired stats capture");if((int)runtime.GetType().GetField("_pausePlannerTab",flags).GetValue(runtime)!=0)throw new System.Exception("Chrome tab required");if(!Paused())throw new System.Exception("User-paused saved scene required");var frozenTime=RunTime();var original=(bool)runtime.GetType().GetField("_nativePauseChromePilot",flags).GetValue(runtime);var oldBackground=UnityEngine.Application.runInBackground;var oldPaused=UnityEditor.EditorApplication.isPaused;UnityEngine.Application.runInBackground=true;UnityEditor.EditorApplication.isPaused=false;
var wanted=new[]{"GC Allocated In Frame","Main Thread","EchoSphere.Canvas.EndFrame","EchoSphere.UI.BuildTree","EchoSphere.UI.ProjectTree","EchoSphere.UI.ResolveCss","EchoSphere.UI.Layout","EchoSphere.UI.Reconcile"};var handles=new System.Collections.Generic.List<Unity.Profiling.LowLevel.Unsafe.ProfilerRecorderHandle>();Unity.Profiling.LowLevel.Unsafe.ProfilerRecorderHandle.GetAvailable(handles);
