var rows=new System.Collections.Generic.List<object>();int phase=0,warm=0,count=0,last=-1;bool timelineEver=false;bool recording=false;double phaseStart=0;var start=UnityEditor.EditorApplication.timeSinceStartup;runtime.SetNativePauseChromePilot(false);UnityEditor.SessionState.SetString("EchoNativePauseChromeProfile","WARM source A1");UnityEditor.EditorApplication.CallbackFunction tick=null;
