tick=()=>{try{if(!UnityEditor.EditorApplication.isPlaying||UnityEditor.EditorApplication.timeSinceStartup-start>240)throw new System.Exception("Play ended/deadline");if(last==UnityEngine.Time.frameCount)return;last=UnityEngine.Time.frameCount;timelineEver|=UnityEditorInternal.ProfilerDriver.enabled;if(!Paused()||System.Math.Abs(RunTime()-frozenTime)>.000001)throw new System.Exception("Scene simulation changed during paired capture");bool native=phase%2==1;
 if(!recording){if(runtime.UsesNativePauseChrome!=native)return;if(++warm<10)return;foreach(var values in samples.Values)values.Clear();recording=true;count=0;phaseStart=UnityEditor.EditorApplication.timeSinceStartup;UnityEditor.SessionState.SetString("EchoNativePauseChromeProfile","RECORD "+(native?"native B":"source A")+(phase/2+1));return;}
 foreach(var pair in recorders)samples[pair.Key].Add(pair.Value.LastValue);if(++count<20)return;
